dagsterplus:index/agentToken:AgentToken.description:
Manages a Dagster+ agent token. The token value is only available at creation time; it cannot be recovered after import. Changing the name forces a new resource.

## Example Usage

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as dagsterplus from "@pulumi/dagsterplus";

const hybridAgent = new dagsterplus.AgentToken("hybrid_agent", {name: "hybrid-agent-token"});
export const agentTokenValue = hybridAgent.token;
```
```python
import pulumi
import pulumi_dagsterplus as dagsterplus

hybrid_agent = dagsterplus.AgentToken("hybrid_agent", name="hybrid-agent-token")
pulumi.export("agentTokenValue", hybrid_agent.token)
```
```csharp
using System.Collections.Generic;
using System.Linq;
using Pulumi;
using Dagsterplus = Pulumi.Dagsterplus;

return await Deployment.RunAsync(() => 
{
    var hybridAgent = new Dagsterplus.Index.AgentToken("hybrid_agent", new()
    {
        Name = "hybrid-agent-token",
    });

    return new Dictionary<string, object?>
    {
        ["agentTokenValue"] = hybridAgent.Token,
    };
});
```
```go
package main

import (
	"github.com/dagster-io/pulumi-dagsterplus/sdk/go/dagsterplus"
	"github.com/pulumi/pulumi/sdk/v3/go/pulumi"
)

func main() {
	pulumi.Run(func(ctx *pulumi.Context) error {
		hybridAgent, err := dagsterplus.NewAgentToken(ctx, "hybrid_agent", &dagsterplus.AgentTokenArgs{
			Name: pulumi.String("hybrid-agent-token"),
		})
		if err != nil {
			return err
		}
		ctx.Export("agentTokenValue", hybridAgent.Token)
		return nil
	})
}
```
