dagsterplus:index/alertPolicy:AlertPolic.description:
Manages a Dagster+ alert policy for a specific deployment.

## Example Usage

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as dagsterplus from "@pulumi/dagsterplus";

// Asset policy — all assets, health status, email notification
const assetHealth = new dagsterplus.AlertPolicy("asset_health", {
    deployment: "prod",
    name: "asset-health-degraded",
    policyType: "asset",
    enabled: true,
    assets: [{
        allAssets: true,
        healthStatus: "degraded",
    }],
    notificationService: {
        type: "email",
        emailAddresses: ["oncall@example.com"],
    },
});
// Asset policy — specific asset selection, specific events, Slack notification
const materializationFailures = new dagsterplus.AlertPolicy("materialization_failures", {
    deployment: "prod",
    name: "critical-asset-failures",
    policyType: "asset",
    enabled: true,
    assets: [{
        assetSelection: "tag:critical",
        specificEvents: [
            "materialization_failure",
            "check_error",
        ],
    }],
    notificationService: {
        type: "slack",
        slackWorkspaceName: "my-workspace",
        slackChannelName: "#data-alerts",
    },
});
// Run policy — all runs, alert on failure, email notification
const runFailures = new dagsterplus.AlertPolicy("run_failures", {
    deployment: "prod",
    name: "run-failures",
    policyType: "run",
    enabled: true,
    runs: [{
        allRuns: true,
        onFailure: true,
    }],
    notificationService: {
        type: "email",
        emailAddresses: ["oncall@example.com"],
    },
});
// Run policy — specific jobs, timeout alert
const longRunningJobs = new dagsterplus.AlertPolicy("long_running_jobs", {
    deployment: "prod",
    name: "long-running-jobs",
    policyType: "run",
    enabled: true,
    runs: [{
        jobNames: [
            "daily_etl",
            "weekly_report",
        ],
        onTimeoutHours: 4,
    }],
    notificationService: {
        type: "pagerduty",
        integrationKey: "abc123def456",
    },
});
// Code location policy — all locations, Microsoft Teams notification
const codeLocationErrors = new dagsterplus.AlertPolicy("code_location_errors", {
    deployment: "prod",
    name: "code-location-errors",
    policyType: "code_location",
    enabled: true,
    codeLocations: [{
        allLocations: true,
    }],
    notificationService: {
        type: "microsoft_teams",
        webhookUrl: "https://my-org.webhook.office.com/webhookb2/...",
    },
});
// Automation policy — all schedules and sensors, min consecutive failures
const sensorFailures = new dagsterplus.AlertPolicy("sensor_failures", {
    deployment: "prod",
    name: "sensor-failures",
    policyType: "automation",
    enabled: true,
    automations: [{
        allSchedulesAndSensors: true,
        includeSchedules: false,
        includeSensors: true,
        minConsecutiveFailures: 3,
    }],
    notificationService: {
        type: "email",
        emailAddresses: ["oncall@example.com"],
    },
});
// Budget policy — alert when Dagster credit spend exceeds threshold
const creditBudget = new dagsterplus.AlertPolicy("credit_budget", {
    deployment: "prod",
    name: "monthly-credit-budget",
    policyType: "budget",
    enabled: true,
    budgets: [{
        operator: "greater_than",
        threshold: 500,
        periodDays: 30,
    }],
    notificationService: {
        type: "email",
        emailAddresses: [
            "finance@example.com",
            "oncall@example.com",
        ],
    },
});
// Insight metric policy — deployment-wide metric threshold
const weeklyCredits = new dagsterplus.AlertPolicy("weekly_credits", {
    deployment: "prod",
    name: "weekly-credit-alert",
    policyType: "insight_metric",
    enabled: true,
    insightMetrics: [{
        metric: "dagster_credits",
        operator: "greater_than",
        threshold: 100,
        periodDays: 7,
    }],
    notificationService: {
        type: "slack",
        slackWorkspaceName: "my-workspace",
        slackChannelName: "#platform-costs",
    },
});
```
