    deployment: "prod",
    name: "my-k8s-location",
    image: "ghcr.io/my-org/my-pipeline:latest",
    codeSource: {
        moduleName: "my_dagster_module",
    },
    containerContext: JSON.stringify({
        k8s: {
            namespace: "dagster",
            env_vars: ["ENV=production"],
            env_secrets: ["my-secret"],
            resources: {
                requests: {
                    memory: "512Mi",
                    cpu: "250m",
                },
                limits: {
                    memory: "1Gi",
                    cpu: "500m",
                },
            },
        },
    }),
});
